def xml(self, attribs = None,elements = None, skipchildren = False):
        """Serialises the FoLiA element to XML, by returning an XML Element (in lxml.etree) for this element and all its children. For string output, consider the xmlstring() method instead."""
        # Create the element
        elem = etree.Element(self.tag)
        # Add attributes
        if attribs is not None:
            for k, v in attribs.items():
                elem.set(k, v)
        # Add children
        if elements is not None:
            for e in elements:
                elem.append(e.xml())
        # Skip children?
        if skipchildren:
            return elem
        # Add content
        if self.content is not None:
            elem.text = self.content
        return elem

